## Fix: Add DynamoDB table to AWS Backup plan

```typescript
// Create backup vault
const vault = new aws.backup.Vault("dynamodb-vault", {
    name: "dynamodb-backup-vault",
});

// Create IAM role for AWS Backup
const backupRole = new aws.iam.Role("backup-role", {
    assumeRolePolicy: JSON.stringify({
        Version: "2012-10-17",
        Statement: [{
            Effect: "Allow",
            Principal: { Service: "backup.amazonaws.com" },
            Action: "sts:AssumeRole",
        }],
    }),
    managedPolicyArns: [
        "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup",
        "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores",
    ],
});

// Create backup plan
const backupPlan = new aws.backup.Plan("dynamodb-backup-plan", {
    name: "daily-dynamodb-backups",
    rules: [{
        ruleName: "daily-backup",
        targetVaultName: vault.name,
        schedule: "cron(0 3 * * ? *)",
        lifecycle: {
            deleteAfter: 35,
        },
    }],
});

// Add DynamoDB tables to backup selection
const backupSelection = new aws.backup.Selection("dynamodb-tables", {
    name: "dynamodb-backup-selection",
    planId: backupPlan.id,
    iamRoleArn: backupRole.arn,
    resources: ["arn:aws:dynamodb:*:*:table/*"],
});
```

